use verus::prelude::*;

verus! {
    /// Given a non‐empty array `a` of 8‐bit signed integers, returns the minimum element.
    /// Requires:
    ///   * a.len() > 0
    /// Ensures:
    ///   * `result` ≤ a[k]  for all 0 ≤ k < a.len()
    ///   * ∃ k < a.len() . result == a[k]
    pub fn nanmin(a: Vec<i8>) -> i8
      requires
        a.len() > 0,
      ensures
        forall(|k: usize| k < a.len() ==> result <= a.index(k)),
        exists(|k: usize| k < a.len() && result == a.index(k)),
    {
        // Initialize min to the first element; we know a.len() ≥ 1.
        let mut min: i8 = a.index(0);
        // We'll scan from i = 1 up to a.len().
        let mut i: usize = 1;
        while i < a.len() {
            // Invariants at the start of each iteration:
            // 1) i is within bounds.
            // 2) min is ≤ every element among a[0..i).
            // 3) min occurs somewhere in a[0..i).
            invariant i <= a.len();
            invariant forall(|k: usize| k < i ==> min <= a.index(k));
            invariant exists(|k: usize| k < i && min == a.index(k));
            decreases a.len() - i;

            let x: i8 = a.index(i);
            if x < min {
                // If we find a smaller value, update min.
                min = x;
            }
            // Now re‐establish the invariants for the next iteration, which will use i' = i+1:

            // 2') min ≤ every element in a[0..i)
            assert forall(|k: usize| k < i ==> min <= a.index(k));

            // 2'') also min ≤ a[i]
            assert min <= a.index(i);

            // 3') min occurs somewhere in a[0..i+1):
            //     either at some k<i (old witness), or at k=i (if we just updated to a[i]).
            assert exists(|k: usize| k < i + 1 && min == a.index(k));

            i += 1;
        }
        // When the loop finishes, i == a.len(), so by the invariants:
        //   * ∀ k < a.len() . min ≤ a[k]
        //   * ∃ k < a.len() . min == a[k]
        min
    }
}